import{z as p,x as n,o as r,c as B,q as t,j as l,D as e,d as s,s as c,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"cgroups","description":"","frontmatter":{"title":"cgroups","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cgroups.md","filePath":"cs/cgroups.md","lastUpdated":1791413859000}'),d={name:"cs/cgroups.md"};function A(m,a,u,g,h,C){const E=n("Mermaid");return r(),B("div",null,[a[2]||(a[2]=t('<h1 id="cgroups" tabindex="-1">cgroups <a class="header-anchor" href="#cgroups" aria-label="Permalink to &quot;cgroups&quot;">​</a></h1><div class="epigraph"><p>控制组把进程放进树里，对 CPU、内存、I/O 等资源记账并施加上限；超限则节流或触发组内 OOM。</p><footer>—— 据 Linux cgroup 文档；Silberschatz 对资源容器的整理</footer></div><p><a href="/cs/namespaces">上一课</a>切开名字，没有切开物理帧与时间片。<a href="/cs/working-set">工作集</a> 与 <a href="/cs/oom-killer">OOM</a> 是全机的。<a href="/cs/timeslice-cfs">调度</a> 可以按组再分权重。缺口是 <strong>cgroup</strong>：可嵌套的进程集合 + 各子系统控制器。v1 多层级与 v2 统一层级合并叙述，不背挂载细节考试。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多租户若只靠 nice，无法保证「这一组最多 2GB、最多 50% CPU」。缺口：进程加入某 cgroup；memory 控制器记账匿名与文件页，超上限则回收该组，再不够则组内 OOM；cpu 控制器给权重或带宽；io 控制器限制 blk-mq 上的比例。接口经 <a href="/cs/sysfs-proc">sysfs</a> 风格的 cgroup 文件系统。</p><p><span class="marginnote">术语翻译：记账就是内核给每组记流水账——这个组此刻用了多少物理页、发过多少 I/O，写在组目录的一堆统计文件里；「限制」则是在缺页、分配、调度这些要花钱的时刻，内核先查一眼当前任务属于哪个组、账上还剩多少额度。</span></p><p><span class="marginnote">v2 要求进程只在叶子组（简化）。委派让非特权用户管理子树。本课不写如何逃出限制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建目录即建组，把 pid 写入 <code>cgroup.procs</code>，写 <code>memory.max</code> 等。内核在缺页、分配、调度选任务时看当前任务的组。与 namespaces 正交：可以只做 cgroup 不做容器，也可以组合。writeback 可以按组节流，接上已有脏页课。</p><p><span class="marginnote">直觉类比：namespaces 管「你看得见什么」——把窗户糊上，别的房间看不见；cgroups 管「你用得多少」——电表水表分户安装，超了先拉你家的闸。容器是两件事叠起来：既看不见别人，也抢不走别人的份额。</span></p>',10)),(r(),l(i,null,{default:e(()=>[c(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20G%5B%22cgroup%20%E6%A0%91%22%5D%0A%20%20G%20--%3E%20CPU%5B%22cpu%20%E6%9D%83%E9%87%8D%2F%E9%85%8D%E9%A2%9D%22%5D%0A%20%20G%20--%3E%20MEM%5B%22memory%20%E4%B8%8A%E9%99%90%22%5D%0A%20%20G%20--%3E%20IO%5B%22io%20%E4%B8%8A%E9%99%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[s("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"cgroup 把负荷控制从「全机抖动」细化到「一组作业的 ΣW」。它不提供独立内核，只提供记账与拒绝/回收。与过度提交同时存在：组内承诺仍可超组上限，于是组内 OOM 先于全机。不要把 Kubernetes 的 YAML 写进 OS 课。",-1)),(r(),l(i,null,{default:e(()=>[c(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALLOC%5B%22%E7%BB%84%E5%86%85%E4%BB%BB%E5%8A%A1%E7%94%B3%E8%AF%B7%E5%86%85%E5%AD%98%22%5D%20--%3E%20ACCT%5B%22memory%20%E6%8E%A7%E5%88%B6%E5%99%A8%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20ACCT%20--%3E%20OVER%7B%22%E8%B6%85%20memory.max%EF%BC%9F%22%7D%0A%20%20OVER%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22%E6%AD%A3%E5%B8%B8%E5%88%86%E9%85%8D%22%5D%0A%20%20OVER%20--%3E%7C%22%E6%98%AF%22%7C%20REC%5B%22%E5%85%88%E5%9B%9E%E6%94%B6%E6%9C%AC%E7%BB%84%E7%9A%84%E5%8F%AF%E5%9B%9E%E6%94%B6%E9%A1%B5%22%5D%0A%20%20REC%20--%3E%20ENOUGH%7B%22%E5%9B%9E%E6%94%B6%E5%A4%9F%E4%BA%86%EF%BC%9F%22%7D%0A%20%20ENOUGH%20--%3E%7C%22%E6%98%AF%22%7C%20OK%0A%20%20ENOUGH%20--%3E%7C%22%E5%90%A6%22%7C%20OOM%5B%22%E7%BB%84%E5%86%85%20OOM%EF%BC%9A%E6%9D%80%E6%9C%AC%E7%BB%84%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20OOM%20--%3E%20NOTE%5B%22%E5%85%A8%E6%9C%BA%E5%8F%AF%E8%83%BD%E8%BF%98%E5%BE%88%E7%A9%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每个控制器文件名的清单。不保证实时组与普通组的所有组合有可移植语义。下一课把 ns + cgroup（再加下一课的 syscall 过滤）收成「容器在 OS 里究竟是什么」。</p><p>后课默认：资源可按组封顶。与命名空间合在一起的容器含义，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cgroup 对进程组记账并限制 CPU/内存/IO。</li><li>与 namespaces 正交；组内 OOM 可先于全机。</li><li>容器作为组合抽象是下一课。</li><li>出处：Linux <code>cgroups(7)</code>；Silberschatz et al., <em>OSC</em>。</li></ul>',5))])}const D=p(d,[["render",A]]);export{f as __pageData,D as default};
